import React, { useState } from "react";
import "./RegPage.css";
import Logo from "../../components/Img/Logo.jpeg";
import { NavLink, useNavigate } from "react-router-dom";
import main from "../../components/Img/main.mp4";
import { useDispatch } from "react-redux";
import { RegUser } from "../../store/slices/UserSlice";
import axios from "axios";  // Добавляем axios для работы с API

const RegPage = ({ User_Data, Loged_User_Data }) => {
  const [value, setValue] = useState("");
  const disatch = useDispatch();
  const navigate = useNavigate();

  if (Loged_User_Data.length !== 0) {
    navigate("/profile");
  }

  const HandlerSubmit = async (e) => {
    e.preventDefault();
    const [FirstName, LastName, Age, Login, Pass, RepeatPass] = e.target;
    const newUser = {
      id: new Date().getTime().toString(),
      FirstName: FirstName.value,
      LastName: LastName.value,
      Age: Age.value,
      Location: "",
      Bio: "",
      Profession: "",
      Hobbies: "",
      Login: Login.value,
      Pass: Pass.value,
      gender: value,
      isEditing: false,
      FriendRequest: [],
      FriendList: [],
      Image: value === "Man" 
        ? "https://ecofishresearch.com/wp-content/uploads/2022/03/690-6904538_men-profile-icon-png-image-free-download-searchpng.png" 
        : "https://st2.depositphotos.com/3250055/8394/v/450/depositphotos_83944630-stock-illustration-female-avatar-profile-picture.jpg", 
      Photo: [],
    };

    if (Pass.value === RepeatPass.value) {
      if (User_Data.find((el) => el.Login === Login.value)) {
        alert("User Already Exists");
      } else {
        try {
          // Отправка данных на backend (Laravel API)
          await fetch("http://localhost:8000/web/register", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(newUser),
          });
        } catch (error) {
          console.log("Submitting user:", newUser);
          console.error("Error during registration:", error);
          alert("Error during registration");
        }
      }
    } else alert("Passwords do not match");

    e.target.reset();
  };

  const checkedGender = (e) => {
    setValue(e.target.value);
  };

  return (
    <div className="RegPage">
      <div className="overplay"></div>
      <video src={main} autoPlay loop muted></video>
      <div className="RegHeader">
        <img className="Regimg" src={Logo} alt="Logo" />
      </div>
      <div className="RegWindow">
        <form onSubmit={HandlerSubmit}>
          <input className="RegInput" type="text" placeholder="First Name..." />
          <input className="RegInput" type="text" placeholder="Last Name..." />
          <input 
            onKeyDown={(e) => {
              if (!/[0-9]/.test(e.key) && e.key !== "Backspace" && e.key !== "Tab") {
                e.preventDefault();
              }
            }} 
            className="RegInput" 
            type="text" 
            placeholder="Age..." 
          />
          <input className="RegInput" type="text" placeholder="Login..." />
          <input className="RegInput" type="password" placeholder="Password..." />
          <input className="RegInput" type="password" placeholder="Repeat Password..." />
          
          <div className="mydict">
            <div>
              <label>
                <input 
                  type="radio" 
                  name="radio"  
                  value="Man" 
                  onChange={checkedGender} 
                />
                <span>Man</span>
              </label>
              <label>
                <input 
                  type="radio" 
                  name="radio" 
                  value="Woman" 
                  onChange={checkedGender} 
                />
                <span>Woman</span>
              </label>
            </div>
          </div>

          <button className="RegButton">Submit</button>
        </form>
        <p>Already have an account? <NavLink to="/Login">Log in.</NavLink></p>
      </div>
    </div>
  );
};

export default RegPage;
